288			return `{"formatVersion":1,"contentId":"` + id + `","graph":` + body + `}`
289		}
290	
291		cases := map[string]struct {
292			data     string
293			field    string
294			location string
295		}{
296			"big direct value before duplicated version": {
297				`{"note":1e400,"formatVersion":2,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
298				"formatVersion", "top level",
299			},
300			"big number in array before duplicated contentId": {
301				`{"note":[1e400,{"deep":1e999}],"formatVersion":1,"contentId":"` + id + `","contentId":"` + id + `","graph":` + graph + `}`,
302				"contentId", "top level",
303			},
304			"big number nested in object before duplicated graph": {
305				`{"meta":{"keep":[1e400]},"formatVersion":1,"contentId":"` + id + `","graph":null,"graph":` + graph + `}`,
306				"graph", "top level",
307			},
308			"null first value with big number before it": {
309				`{"note":-1e400,"contentId":null,"contentId":"` + id + `","formatVersion":1,"graph":` + graph + `}`,
310				"contentId", "top level",
311			},
312			"duplicate before the big number": {
313				`{"formatVersion":2,"formatVersion":1,"note":1e400,"contentId":"` + id + `","graph":` + graph + `}`,
314				"formatVersion", "top level",
315			},
316			"big number nested inside graph before duplicated datasets": {
317				doc(`{"note":{"deep":[1e400]},"datasets":[],"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`),
318				"datasets", `in "graph"`,
319			},
320			"big direct value in record before duplicated name": {
321				doc(`{"datasets":[{"note":1e400,"name":"A","name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`),
322				"name", `index 0 of "datasets"`,
323			},
324			"big number nested in record before duplicated upstreams": {
325				doc(`{"datasets":[{"name":"A","upstreams":[]},{"vals":[[1e400],{"x":[1e999]}],"name":"B","upstreams":["A"],"upstreams":["A"]}]}`),
326				"upstreams", `index 1 of "datasets"`,
327			},
328		}
329		for name, tc := range cases {
330			t.Run(name, func(t *testing.T) {
331				_, err := ParseSnapshot([]byte(tc.data))
332				if !errors.Is(err, ErrInvalidArgument) {
333					t.Fatalf("err = %v, want ErrInvalidArgument", err)
334				}
335				if !strings.Contains(err.Error(), `"`+tc.field+`"`) {
336					t.Errorf("err = %q, want it to name duplicated field %q", err, tc.field)
337				}
338				if !strings.Contains(err.Error(), tc.location) {
339					t.Errorf("err = %q, want it to locate the duplicate %q", err, tc.location)
340				}
341			})
342		}
343	}
