436	// TestParseSnapshotRejectsUnicodeFoldDuplicates: two keys that the JSON
437	// reader resolves to the same struct field through Unicode simple case
438	// folding — not merely ASCII case — make the snapshot ambiguous. U+017F
439	// LATIN SMALL LETTER LONG S ("ſ") is a fold equivalent of "s", so
440	// "formatVerſion" and "formatVersion" select the same field, as do
441	// "dataſets"/"datasets" and "upſtreams"/"upstreams". Writing the rune
442	// directly or via a JSON escape must not matter, and identical values, a null
443	// first value, or reversed declaration order must not save the document. The
444	// error names the canonical field and, inside a datasets record, its index.
445	func TestParseSnapshotRejectsUnicodeFoldDuplicates(t *testing.T) {
446		const (
447			longS = "ſ" // U+017F LATIN SMALL LETTER LONG S, folds to ASCII "s"
448			// longSEscape is the JSON escape spelling of the same rune as literal
449			// document bytes (backslash, u, 0, 1, 7, f).
450			longSEscape = "\\" + "u017f"
451		)
452		graph := `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`
453		id := snapshotOf(t, graph).ContentID
454		doc := func(body string) string {
455			return `{"formatVersion":1,"contentId":"` + id + `","graph":` + body + `}`
456		}
457	
458		cases := map[string]struct {
459			data  string
460			field string
461		}{
462			"long s version 2 then 1": {
463				`{"formatVer` + longS + `ion":2,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
464				"formatVersion",
465			},
466			"long s version reversed order": {
467				`{"formatVersion":1,"formatVer` + longS + `ion":1,"contentId":"` + id + `","graph":` + graph + `}`,
468				"formatVersion",
469			},
470			"long s version identical values": {
471				`{"formatVer` + longS + `ion":1,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
472				"formatVersion",
473			},
474			"long s version via JSON escape": {
475				`{"formatVer` + longSEscape + `ion":2,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
476				"formatVersion",
477			},
478			"null long s version then valid": {
479				`{"formatVer` + longS + `ion":null,"formatVersion":1,"contentId":"` + id + `","graph":` + graph + `}`,
480				"formatVersion",
481			},
482			"datasets versus long s datasets": {
483				doc(`{"data` + longS + `ets":[],"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`),
484				"datasets",
485			},
486			"long s datasets via JSON escape": {
487				doc(`{"data` + longSEscape + `ets":[],"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`),
488				"datasets",
489			},
490			"upstreams versus long s upstreams": {
491				doc(`{"datasets":[{"name":"A","upstreams":[]},{"name":"B","up` + longS + `treams":["A"],"upstreams":["A"]}]}`),
492				"upstreams",
493			},
494			"long s upstreams via JSON escape": {
495				doc(`{"datasets":[{"name":"A","upstreams":[]},{"name":"B","up` + longSEscape + `treams":["A"],"upstreams":["A"]}]}`),
496				"upstreams",
497			},
498			"null long s upstreams then valid": {
499				doc(`{"datasets":[{"name":"A","upstreams":[]},{"name":"B","up` + longS + `treams":null,"upstreams":["A"]}]}`),
500				"upstreams",
501			},
502		}
503		for name, tc := range cases {
504			t.Run(name, func(t *testing.T) {
505				// Every "escape" case really must carry ASCII escape bytes.
506				if strings.Contains(name, "escape") && !strings.Contains(tc.data, longSEscape) {
507					t.Fatalf("test case %q does not actually use a JSON escape", name)
508				}
509				_, err := ParseSnapshot([]byte(tc.data))
510				if !errors.Is(err, ErrInvalidArgument) {
511					t.Fatalf("err = %v, want ErrInvalidArgument", err)
512				}
513				if !strings.Contains(err.Error(), `"`+tc.field+`"`) {
514					t.Errorf("err = %q, want it to name canonical field %q", err, tc.field)
515				}
516			})
517		}
518	
519		// The duplicate lives in the second dataset record; the error must locate
520		// that record by its datasets array index even for a Unicode-fold key.
521		indexed := doc(`{"datasets":[{"name":"A","upstreams":[]},{"up` + longS + `treams":["A"],"name":"B","upstreams":["A"]}]}`)
522		if _, err := ParseSnapshot([]byte(indexed)); err == nil || !strings.Contains(err.Error(), "index 1") {
523			t.Errorf("err = %v, want the datasets index of the offending record", err)
524		}
525	
526		// A top-level long-s spelling twice also collides at the top level.
527		twice := `{"formatVer` + longS + `ion":1,"formatVer` + longS + `ion":1,"contentId":"` + id + `","graph":` + graph + `}`
528		if _, err := ParseSnapshot([]byte(twice)); err == nil ||
529			!strings.Contains(err.Error(), `"formatVersion"`) ||
530			!strings.Contains(err.Error(), "top level") {
531			t.Errorf("err = %v, want a top-level formatVersion duplicate error", err)
532		}
533	}
