}

// P is a shorthand for building name/parents pairs in test tables.
func P(name string, parents ...string) struct {
	name    string
	parents []string
} {
	return struct {
		name    string
		parents []string
	}{name, parents}
}

func planOf(changes ...PlanChange) Plan {
	return Plan{Changes: changes}
