package chainledger

import (
	"reflect"
	"testing"
)

func TestScratchSnapshotIndependence(t *testing.T) {
	// Two roots A and B, intermediate M depends on both, downstream D on M.
	graph := buildGraph(t, P("A"), P("B"), P("M", "A", "B"), P("D", "M"))

	snap, err := BuildSnapshot(graph)
	if err != nil {
		t.Fatalf("BuildSnapshot: %v", err)
	}
	wantID := snap.ContentID
	wantBytes, _ := MarshalSnapshot(snap)

	// Caller replaces a name inside the original upstream list in place.
	graph["M"].Parents[0] = "HACK"
	// then removes a node from the original graph.
	delete(graph, "A")

	if snap.ContentID != wantID {
		t.Errorf("content id changed: got %s want %s", snap.ContentID, wantID)
	}
	gotBytes, _ := MarshalSnapshot(snap)
	if string(gotBytes) != string(wantBytes) {
		t.Errorf("snapshot bytes changed after graph edit")
	}
	parsed, err := ParseSnapshot(gotBytes)
	if err != nil {
		t.Fatalf("old snapshot no longer parses: %v", err)
	}
	if parsed.ContentID != wantID {
		t.Errorf("parsed content id changed")
	}
	// All original nodes must survive.
	names := map[string]bool{}
	for _, ds := range snap.Graph.Datasets {
		names[ds.Name] = true
	}
	for _, n := range []string{"A", "B", "M", "D"} {
		if !names[n] {
			t.Errorf("snapshot lost node %q", n)
		}
	}
}

func TestScratchTwoSnapshotsIndependent(t *testing.T) {
	graph := buildGraph(t,
		P("A"), P("B"),
		P("M", "A", "B"),
		P("N", "A", "B"), // identical upstream lists
		P("D", "M"),
	)
	s1, err := BuildSnapshot(graph)
	if err != nil {
		t.Fatal(err)
	}
	s2, err := BuildSnapshot(graph)
	if err != nil {
		t.Fatal(err)
	}
	b1, _ := MarshalSnapshot(s1)
	b2, _ := MarshalSnapshot(s2)
	if s1.ContentID != s2.ContentID || string(b1) != string(b2) {
		t.Fatalf("two snapshots of one graph differ initially")
	}

	idx := func(s *SnapshotFile, name string) int {
		for i := range s.Graph.Datasets {
			if s.Graph.Datasets[i].Name == name {
				return i
			}
		}
		return -1
	}
	// Edit s1: upstream record in place + append, and dataset record edit.
	i := idx(s1, "M")
	s1.Graph.Datasets[i].Upstreams[0] = "X"
	s1.Graph.Datasets[i].Upstreams = append(s1.Graph.Datasets[i].Upstreams, "Y")
	s1.Graph.Datasets[idx(s1, "D")].Name = "DD"

	// s2 must be untouched.
	b2after, _ := MarshalSnapshot(s2)
	if string(b2after) != string(b2) {
		t.Errorf("second snapshot changed after editing first")
	}
	mi := idx(s2, "M")
	if got := s2.Graph.Datasets[mi].Upstreams; !reflect.DeepEqual(got, []string{"A", "B"}) {
		t.Errorf("s2 M upstreams = %v, want [A B]", got)
	}
	ni := idx(s2, "N")
	if got := s2.Graph.Datasets[ni].Upstreams; !reflect.DeepEqual(got, []string{"A", "B"}) {
		t.Errorf("s2 N upstreams = %v, want [A B] (shared-list alias)", got)
	}
	// original graph untouched
	if got := graph["M"].Parents; !reflect.DeepEqual(got, []string{"A", "B"}) {
		t.Errorf("graph M parents = %v, want [A B]", got)
	}
	if got := graph["D"].Dataset; got != "D" {
		t.Errorf("graph D node renamed to %q", got)
	}
}

func TestScratchBuildFailsOnCorruptGraph(t *testing.T) {
	graph := buildGraph(t, P("A"), P("B"), P("M", "A", "B"))
	old, err := BuildSnapshot(graph)
	if err != nil {
		t.Fatal(err)
	}
	oldBytes, _ := MarshalSnapshot(old)
	dumpBefore := dump(graph)

	// Corrupt: M references a missing upstream, without registering it.
	graph["M"].Parents = []string{"GHOST"}
	snap, err := BuildSnapshot(graph)
	if err == nil {
		t.Fatalf("BuildSnapshot on corrupt graph returned %v", snap)
	}
	if dump(graph) != dumpBefore {
		t.Errorf("failed build mutated graph:\n got %s\nwant %s", dump(graph), dumpBefore)
	}
	// Old snapshot still exports & parses.
	if _, err := ParseSnapshot(oldBytes); err != nil {
		t.Errorf("old snapshot broke: %v", err)
	}
}

